SELECT COUNT(*) AS total_wilds FROM wild_tiles WHERE world_id=1;
SELECT COUNT(*) AS new_tiles_on_sea FROM wild_tiles w JOIN world_map m ON m.id=w.world_id WHERE w.id BETWEEN 521 AND 1220 AND SUBSTRING(m.terrain_data,w.y*m.size+w.x+1,1)<>'0';
SELECT COUNT(*) AS new_tile_coordinate_conflicts FROM wild_tiles w JOIN wild_tiles o ON w.world_id=o.world_id AND w.x=o.x AND w.y=o.y AND w.id<>o.id WHERE w.id BETWEEN 521 AND 1220;
SELECT COUNT(*) AS new_tiles_on_cities FROM wild_tiles w JOIN player_cities c ON c.world_id=w.world_id JOIN world_map m ON m.id=w.world_id WHERE w.id BETWEEN 521 AND 1220 AND w.x BETWEEN LEAST(c.x,m.size-IF(c.owner_id IS NULL,1,2)) AND LEAST(c.x,m.size-IF(c.owner_id IS NULL,1,2))+IF(c.owner_id IS NULL,0,1) AND w.y BETWEEN LEAST(c.y,m.size-IF(c.owner_id IS NULL,1,2)) AND LEAST(c.y,m.size-IF(c.owner_id IS NULL,1,2))+IF(c.owner_id IS NULL,0,1);
SELECT COUNT(*) AS invalid_new_resource_state FROM wild_tiles WHERE id BETWEEN 521 AND 1220 AND (occupied<>0 OR occupied_by IS NOT NULL OR mined<>0 OR level NOT BETWEEN 1 AND 6 OR NOT JSON_VALID(garrison) OR (type IN ('grainfield','ironworks','oil','rarefactory') AND total_res<>level*800) OR (type IN ('forest','hill','swamp') AND total_res<>0));
